import { useState } from 'react'
import { ScrollView, Text, View } from 'react-native'
import { useSafeAreaInsets } from 'react-native-safe-area-context'
import { Check } from 'lucide-react-native'
import { colors, Theme, useTheme } from '@/theme'
import { defineStyles } from '@/utils/defineStyles'
import Animated, {
	FadeIn,
	FadeOut,
	LinearTransition
} from 'react-native-reanimated'
import {
	AnimatedText,
	AnimatedTouchableWithoutFeedback,
	AnimatedLinearGradient,
	Button,
	Grabber,
	SegmentedControl,
	SnapSlider
} from '@/components'
import { useCurrentOrganization } from '@/utils/hooks'
import { CreditProductId, RevenueCatSubscriptionProductId } from '@/types'
import { Plan, PLANS } from '@/constants'

function getPlanToProductId({
	planType,
	plan,
	credits
}: {
	planType: string
	plan: string
	credits: number
}) {
	if (planType === 'monthly') {
		if (plan === 'pro') {
			if (credits === 20) {
				return RevenueCatSubscriptionProductId.USAGE_PRO_20_MONTHLY
			}
			if (credits === 50) {
				return RevenueCatSubscriptionProductId.USAGE_PRO_50_MONTHLY
			}
			if (credits === 100) {
				return RevenueCatSubscriptionProductId.USAGE_PRO_100_MONTHLY
			}
		}
		if (plan === 'max') {
			if (credits === 200) {
				return RevenueCatSubscriptionProductId.USAGE_PRO_200_MONTHLY
			}
			if (credits === 300) {
				return RevenueCatSubscriptionProductId.USAGE_PRO_300_MONTHLY
			}
			if (credits === 400) {
				return RevenueCatSubscriptionProductId.USAGE_PRO_400_MONTHLY
			}
			if (credits === 500) {
				return RevenueCatSubscriptionProductId.USAGE_PRO_500_MONTHLY
			}
			if (credits === 600) {
				return RevenueCatSubscriptionProductId.USAGE_PRO_600_MONTHLY
			}
			if (credits === 750) {
				return RevenueCatSubscriptionProductId.USAGE_PRO_750_MONTHLY
			}
			if (credits === 900) {
				return RevenueCatSubscriptionProductId.USAGE_PRO_900_MONTHLY
			}
		}
	}
	if (planType === 'yearly') {
		if (plan === 'pro') {
			if (credits === 20) {
				return RevenueCatSubscriptionProductId.USAGE_PRO_20_YEARLY
			}
			if (credits === 50) {
				return RevenueCatSubscriptionProductId.USAGE_PRO_50_YEARLY
			}
			if (credits === 100) {
				return RevenueCatSubscriptionProductId.USAGE_PRO_100_YEARLY
			}
		}
	}
	return null
}

export const UpgradePlanScreen = ({
	onPurchase,
	isPurchasing
}: {
	onPurchase: (
		productId: CreditProductId | RevenueCatSubscriptionProductId
	) => void
	isPurchasing: boolean
}) => {
	const { theme } = useTheme()
	const insets = useSafeAreaInsets()
	const { currentOrganization } = useCurrentOrganization()

	const [planType, setPlanType] = useState('Monthly')
	const [expandedPlan, setExpandedPlan] = useState<'pro' | 'max'>('pro')
	const [selectedCredits, setSelectedCredits] = useState<
		Record<string, number>
	>({
		pro: 20,
		max: 200
	})

	const handlePlanPress = (planId: 'pro' | 'max') => {
		if (expandedPlan !== planId) {
			setExpandedPlan(planId)
		}
	}

	const getPrice = (plan: Plan) => {
		if (plan.creditTiers) {
			const selectedTier = plan.creditTiers.find(
				(tier) => tier.credits === selectedCredits[plan.id]
			)
			if (selectedTier) {
				const price =
					planType === 'Monthly'
						? selectedTier.monthlyPrice
						: selectedTier.yearlyPrice
				return `$${price} / ${planType === 'Monthly' ? 'month' : 'year'}`
			}
		}
		const price = planType === 'Monthly' ? plan.monthlyPrice : plan.yearlyPrice
		return `$${price} / ${planType === 'Monthly' ? 'month' : 'year'}`
	}

	const selectedPlan = PLANS.find((p) => p.id === expandedPlan)

	return (
		<View style={styles.container(theme)}>
			<Grabber />
			<ScrollView
				showsVerticalScrollIndicator={false}
				contentContainerStyle={styles.content}
			>
				<View style={styles.header}>
					<Text style={styles.title(theme)}>Upgrade to Pro</Text>
					<Text style={styles.subtitle(theme)}>
						Get 2 months free with annual
					</Text>
				</View>

				<SegmentedControl
					options={['Monthly', 'Yearly']}
					selectedOption={planType}
					onOptionPress={(option) => {
						setPlanType(option as 'Monthly' | 'Yearly')
						if (option === 'Yearly' && expandedPlan === 'max') {
							setExpandedPlan('pro')
						}
					}}
				/>

				{PLANS.map((plan) => {
					if (plan.id === 'max' && planType === 'Yearly') return null
					const isExpanded = expandedPlan === plan.id
					return (
						<AnimatedTouchableWithoutFeedback
							key={plan.id}
							onPress={() => handlePlanPress(plan.id)}
							style={{ overflow: 'hidden' }}
						>
							<Animated.View
								layout={LinearTransition}
								style={[styles.card(theme, isExpanded)]}
							>
								{isExpanded && (
									<AnimatedLinearGradient
										colors={[colors[theme].gray[900], colors[theme].gray[700]]}
										style={styles.cardBackground}
										entering={FadeIn}
										exiting={FadeOut}
									/>
								)}
								<View style={{ gap: 4 }}>
									<AnimatedText
										style={[
											styles.planText(theme, isExpanded),
											plan.id === 'max' && styles.maxTextStyle
										]}
									>
										{plan.name}
									</AnimatedText>
									{isExpanded && (
										<Animated.View
											style={{ gap: 4 }}
											entering={FadeIn}
											exiting={FadeOut}
										>
											<View style={styles.creditsRow}>
												<Text style={styles.planText(theme)}>
													{plan.creditTiers
														? `${selectedCredits[plan.id]}k credits / month`
														: `${plan.credits}k credits / month`}
												</Text>
												<View style={styles.checkmark(theme)}>
													<Check
														size={13}
														color={colors[theme].gray[900]}
														strokeWidth={3.5}
													/>
												</View>
											</View>

											<Text style={styles.planPrice(theme)}>
												{getPrice(plan)}
											</Text>
										</Animated.View>
									)}
								</View>
								{plan.creditTiers && isExpanded && (
									<SnapSlider
										snapPoints={plan.creditTiers.map((tier) => tier.credits)}
										value={selectedCredits[plan.id]}
										onChange={(value) =>
											setSelectedCredits((prev) => ({
												...prev,
												[plan.id]: value
											}))
										}
									/>
								)}
								{plan.creditTiers && isExpanded && (
									<View style={styles.divider(theme)} />
								)}
								{isExpanded && (
									<Animated.View
										style={styles.featuresContainer}
										entering={FadeIn}
										exiting={FadeOut}
									>
										{plan.features.map((feature, index) => (
											<View key={index} style={styles.feature}>
												<Text style={styles.planText(theme)}>{feature}</Text>
												<Check size={18} color={colors[theme].background} />
											</View>
										))}
									</Animated.View>
								)}
							</Animated.View>
						</AnimatedTouchableWithoutFeedback>
					)
				})}
			</ScrollView>

			<View style={{ paddingBottom: insets.bottom + 16 }}>
				<Button
					loading={!currentOrganization || isPurchasing}
					text={`Upgrade to ${selectedPlan?.name}`}
					onPress={() => {
						const productId = getPlanToProductId({
							planType: planType.toLowerCase(),
							plan: expandedPlan,
							credits: selectedCredits[expandedPlan]
						})
						if (!productId) {
							throw new Error('Invalid product ID')
						}
						onPurchase(productId)
					}}
					variant="gradient"
				/>
				<View style={{ marginTop: 10, flexDirection: 'column', gap: 4 }}>
					<Text style={styles.minimalText(theme)}>
						Auto renews for{' '}
						<Text style={{ fontWeight: '600' }}>
							{getPrice(selectedPlan as Plan)}
						</Text>{' '}
						until cancelled.
					</Text>
					<Text style={styles.minimalText(theme)}>
						You may cancel at any time.
					</Text>
				</View>
			</View>
		</View>
	)
}

const styles = defineStyles({
	container: (theme: Theme) => ({
		flex: 1,
		backgroundColor: colors[theme].background,
		paddingHorizontal: 20
	}),
	content: {
		gap: 20
	},
	header: {
		paddingTop: 20,
		gap: 10
	},
	title: (theme: Theme) => ({
		fontSize: 24,
		fontWeight: '600',
		color: colors[theme].gray[900]
	}),
	subtitle: (theme: Theme) => ({
		fontSize: 16,
		color: colors[theme].gray[500]
	}),
	card: (theme: Theme, isExpanded?: boolean) => ({
		overflow: 'hidden',
		borderWidth: 1,
		borderColor: isExpanded ? colors[theme].gray[50] : colors[theme].gray[400],
		borderRadius: 12,
		paddingHorizontal: 20,
		paddingVertical: 12,
		gap: 18
	}),
	cardBackground: {
		position: 'absolute',
		top: 0,
		left: 0,
		right: 0,
		bottom: 0,
		borderRadius: 11,
		borderCurve: 'continuous'
	},
	planText: (theme: Theme, isExpanded?: boolean) => ({
		fontSize: 16,
		fontWeight: '500',
		color:
			isExpanded !== undefined
				? isExpanded
					? colors[theme].gray[25]
					: colors[theme].gray[400]
				: colors[theme].gray[25],
		transitionProperty: 'color',
		transitionDuration: '300ms'
	}),
	planPrice: (theme: Theme) => ({
		fontSize: 16,
		fontWeight: '500',
		color: colors[theme].gray[400]
	}),
	creditsRow: {
		flexDirection: 'row',
		alignItems: 'center',
		justifyContent: 'space-between'
	},
	checkmark: (theme: Theme) => ({
		width: 18,
		height: 18,
		borderRadius: 9,
		backgroundColor: colors[theme].background,
		alignItems: 'center',
		justifyContent: 'center'
	}),
	featuresContainer: {
		gap: 4
	},
	feature: {
		flexDirection: 'row',
		alignItems: 'center',
		justifyContent: 'space-between'
	},
	actionButton: (theme: Theme, isCurrentPlan?: boolean) => ({
		backgroundColor:
			isCurrentPlan !== undefined
				? isCurrentPlan
					? colors[theme].gray[50]
					: colors[theme].gray[900]
				: colors[theme].gray[900],
		borderRadius: 16,
		paddingVertical: 16,
		alignItems: 'center',
		transitionProperty: ['backgroundColor', 'color'],
		transitionDuration: '300ms'
	}),
	actionButtonCurrent: (theme: Theme) => ({
		backgroundColor: colors[theme].gray[50]
	}),
	actionButtonText: (theme: Theme, isCurrentPlan?: boolean) => ({
		fontSize: 16,
		fontWeight: '600',
		color:
			isCurrentPlan !== undefined
				? isCurrentPlan
					? colors[theme].gray[400]
					: colors[theme].white
				: colors[theme].white,
		transitionProperty: ['color'],
		transitionDuration: '300ms'
	}),
	divider: (theme: Theme) => ({
		height: 1,
		backgroundColor: colors[theme].gray[700]
	}),
	maxTextStyle: {
		fontWeight: '900',
		fontStyle: 'italic',
		letterSpacing: -2
	},
	minimalText: (theme: Theme) => ({
		fontSize: 12,
		color: colors[theme].gray[500],
		textAlign: 'center'
	})
})
